 ctx.fillStyle='#222';ctx.textAlign='center';ctx.font='bold 38px "TH SarabunPSK"';const titleLines=wrapped(ctx,reportTitle(s,r,year)+' (รายสัปดาห์)',2700);titleLines.forEach((t,i)=>ctx.fillText(t,(total+150)/2,60+i*33));ctx.font='32px "TH SarabunPSK"';ctx.fillText('ระหว่างวันที่ '+fmt(r.start)+' – '+fmt(r.end),(total+150)/2,60+titleLines.length*33+10);
 const y0=165,headerH=140;
