let dbPromise,memoryWorkspace,cachedHistoryReference;const getDB=()=>dbPromise??=new Promise((resolve,reject)=>{try{const q=indexedDB.open('pn-weekly',1);q.onupgradeneeded=()=>q.result.createObjectStore('data');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);}catch(e){reject(e);}});
export async function readStore(options={}){try{const db=await getDB();return await new Promise((resolve,reject)=>{const tx=db.transaction('data'),store=tx.objectStore('data'),q=store.get('workspace');q.onsuccess=()=>{const data=q.result;if(data?.importHistoryCached&&options.deferHistory){delete data.importHistoryCached;data.importHistoryDeferred=true;resolve(data);}else if(data?.importHistoryCached){const history=store.get('importHistory');history.onsuccess=()=>{delete data.importHistoryCached;data.importHistory=history.result||[];cachedHistoryReference=data.importHistory;resolve(data);};history.onerror=()=>reject(history.error);}else resolve(data);};q.onerror=()=>reject(q.error);});}catch{return memoryWorkspace?clone(memoryWorkspace):undefined;}}
export async function writeStore(state,expectedRevision){try{const db=await getDB();return await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite'),s=tx.objectStore('data');let conflict=false;const save=current=>{if(expectedRevision!==undefined&&current!==undefined&&current!==expectedRevision){conflict=true;tx.abort();return;}const {importHistory,...hot}=state;if(Array.isArray(importHistory)){hot.importHistoryCached=true;if(importHistory!==cachedHistoryReference)s.put(importHistory,'importHistory');}s.put(hot,'workspace');s.put(state.revision||0,'revision');};const q=s.get('revision');q.onsuccess=()=>{if(q.result===undefined&&expectedRevision!==undefined){const legacy=s.get('workspace');legacy.onsuccess=()=>save(legacy.result?.revision);}else save(q.result);};tx.oncomplete=()=>{if(Array.isArray(state.importHistory))cachedHistoryReference=state.importHistory;resolve({durable:true});};tx.onabort=()=>reject(Error(conflict?'ข้อมูลถูกแก้ไขจากอีกแท็บ กรุณารีเฟรชหน้าเว็บก่อนบันทึก':'บันทึกข้อมูลบนอุปกรณ์ไม่สำเร็จ'));tx.onerror=()=>reject(tx.error);});}catch(e){if(e?.message?.includes('อีกแท็บ'))throw e;memoryWorkspace=clone(state);return {durable:false};}}


