const importCloud=(payload,revision,source)=>request('pn2_import_workspace',{payload:jsonImportPayload(payload),expected_revision:revision,source});
const importChangesCloud=(changes,revision,source)=>request('pn2_import_changes',{changes,expected_revision:revision,source});
