export const plannetColumns=[['sourceId','ID Code','โครงการ'],['workCode','รหัสงาน','โครงการ'],['title','ลักษณะงาน','โครงการ'],['routeNumber','หมายเลขทางหลวง','ช่วงทาง'],['controlSection','ตอนควบคุม','ช่วงทาง'],['sectionName','ชื่อตอน/โครงการ','ช่วงทาง'],['kmStart','กม.เริ่มต้น','ช่วงทาง'],['kmEnd','กม.สิ้นสุด','ช่วงทาง'],['routeNote','หมายเหตุช่วงทาง','ช่วงทาง'],['direction','ทิศทาง','ช่วงทาง'],['distance','ระยะทาง กม.จริง','ผลผลิต'],['twoLaneDistance','ระยะทาง/2 ช่องจราจร','ผลผลิต'],['quantity','จำนวน','ปริมาณงาน'],['unit','หน่วย','ปริมาณงาน'],['signedAt','ลงวันที่','สัญญา'],['contract','เลขที่','สัญญา'],['start','เริ่มต้น','สัญญา'],['end','สิ้นสุด','สัญญา'],['sourceExtendedEnd','ขยายระยะเวลา','สัญญา'],['budgetAct','พ.ร.บ.','งบประมาณ'],['allocatedBudget','จัดสรร','งบประมาณ'],['contractValue','วงเงินสัญญา','งบประมาณ'],['poAmount','PO','งบประมาณ'],['duration','ระยะเวลา (วัน)','งบประมาณ'],['sourceExtensionDays','ขยายระยะเวลา (วัน)','งบประมาณ'],['carryBudget','เงินกันไปปี','งบประมาณ'],['contractorRaw','ผู้ดำเนินการ','ผู้รับจ้าง'],['sourceActual','ผลงาน (%)','การดำเนินงานสะสม'],['deliveryDate','วันส่งมอบงาน','การดำเนินงานสะสม'],['acceptanceDate','วันตรวจรับงาน','การดำเนินงานสะสม'],['paidFiscal','ภายในปีงบประมาณ','เบิกจ่าย'],['paidCarry','เบิกจ่ายในส่วนเงินกัน','เบิกจ่าย'],['actualCost','รวมโครงการ','เบิกจ่าย'],['paymentMonth','เดือน/ปี','เบิกจ่าย'],['sourceStatus','สถานะ','เบิกจ่าย'],['budgetAccount','บัญชีงบประมาณ','ข้อมูลประกอบ'],['note','หมายเหตุ','ข้อมูลประกอบ'],['contractorCanonicalName','ชื่อผู้รับจ้างมาตรฐาน','ข้อมูลอ้างอิง'],['contractorAliases','ชื่อเรียกอื่นผู้รับจ้าง JSON','ข้อมูลอ้างอิง']];
const plannetNumeric=new Set(['distance','twoLaneDistance','quantity','budgetAct','allocatedBudget','contractValue','poAmount','duration','sourceExtensionDays','carryBudget','sourceActual','paidFiscal','paidCarry','actualCost']);
export const cleanSource=v=>String(v??'').replace(/_x000D_/gi,'\n').replace(/_x0009_/gi,'\t').replace(/\r/g,'').trim();
export const personnelDuty=(group,ordinal)=>group==='inspection'?(ordinal===1?'ประธาน':'กรรมการ'):(ordinal===1?'ผู้ควบคุมงาน':'ผู้ช่วยผู้ควบคุมงาน');
export function parsePersonnelDetails(value,group='supervision'){const entries=[];let buffer='',open=0;for(const part of cleanSource(value).split(/\n+/)){if(!part.trim())continue;if(!open&&buffer){entries.push(buffer);buffer='';}buffer+=(buffer?' ':'')+part;open+=(part.match(/\(/g)||[]).length-(part.match(/\)/g)||[]).length;}if(buffer)entries.push(buffer);const seen=new Set(),result=[];for(const line of entries){let source=line.replace(/^\s*\d+(?:\.\d+)*[.)]?\s*/,''),name='',position='',depth=0;for(const ch of source){if(ch==='('){if(depth++)position+=ch;}else if(ch===')'){if(depth>0){if(--depth)position+=ch;}else name+=ch;}else if(depth)position+=ch;else name+=ch;}if(depth)throw Error('วงเล็บตำแหน่งบุคลากรไม่ครบ');name=name.normalize('NFKC').replace(/\s+/g,' ').trim();position=position.replace(/\s+/g,' ').trim();if(!name||seen.has(name))continue;seen.add(name);const ordinal=result.length+1;result.push({name,position,ordinal,duty:personnelDuty(group,ordinal)});}return result;}
export function parsePersonnel(value){return parsePersonnelDetails(value).map(x=>x.name);}
