export function g4RowsToPersonnel(rows,sheet=''){const header=rows.slice(0,6).find(r=>r.some(v=>cleanSource(v)==='ID Code'));if(!header)return [];const idCol=header.findIndex(v=>cleanSource(v)==='ID Code'),supervisorCol=header.findIndex(v=>cleanSource(v)==='ผู้ควบคุมงาน'),second=rows[rows.indexOf(header)+1]||[],flatCommitteeCol=header.findIndex(v=>cleanSource(v)==='ตรวจรับพัสดุ'),committeeCol=flatCommitteeCol>=0?flatCommitteeCol:second.findIndex(v=>cleanSource(v)==='ตรวจรับพัสดุ'),contractCol=header.findIndex(v=>cleanSource(v)==='เลขที่');if(supervisorCol<0||committeeCol<0)throw Error('ไม่พบคณะกรรมการตรวจรับพัสดุ/ผู้ควบคุมงาน');return rows.slice(rows.indexOf(header)+(flatCommitteeCol>=0?1:2)).filter(r=>cleanSource(r[idCol])||cleanSource(r[contractCol])).map((r,i)=>{const committeeMembers=parsePersonnelDetails(r[committeeCol],'inspection'),supervisorMembers=parsePersonnelDetails(r[supervisorCol],'supervision');for(const [members,label,group]of [[committeeMembers,'บทบาทตรวจรับ JSON','inspection'],[supervisorMembers,'บทบาทผู้ควบคุม JSON','supervision']]){const c=header.findIndex(v=>cleanSource(v)===label);if(c>=0&&r[c]){let roles;try{roles=JSON.parse(r[c]);}catch{throw Error('รูปแบบบทบาทบุคลากรไม่ถูกต้อง');}if(!Array.isArray(roles)||roles.length!==members.length)throw Error('จำนวนบทบาทไม่ตรงรายชื่อ');members.forEach((m,j)=>{if(!(group==='inspection'?['ประธาน','กรรมการ']:['ผู้ควบคุมงาน','ผู้ช่วยผู้ควบคุมงาน']).includes(roles[j]))throw Error('บทบาทไม่ตรงประเภทบุคลากร');m.duty=roles[j];});}}return {sourceId:cleanSource(r[idCol]),contract:cleanSource(r[contractCol]),committee:committeeMembers.map(x=>x.name),supervisors:supervisorMembers.map(x=>x.name),committeeMembers,supervisorMembers,sourceRow:i+6,sourceSheet:sheet};});}
export function previewPersonnelImport(s,records,year,funding){const seen=new Set();return records.map((row,index)=>{const r=registrySourceMatch(s,{sourceId:row.sourceId,contract:row.contract},year,funding),errors=[];if(!r)errors.push('ไม่พบ ID Code ในทะเบียนของปีและกลุ่มงบที่เลือก');if(seen.has(row.sourceId||contractKey(row.contract)))errors.push('ID Code หรือสัญญาซ้ำในไฟล์');seen.add(row.sourceId||contractKey(row.contract));if(r&&row.contract&&contractKey(row.contract)!==contractKey(r.contract))errors.push('ID Code ตรงแต่เลขสัญญาต่าง กรุณาตรวจทะเบียน');const simple=xs=>xs.map(({name,position,ordinal,duty})=>({name:name.normalize('NFKC'),position,ordinal,duty})),before=r?{committeeMembers:simple(assignmentDetails(s,r,'inspection')),supervisorMembers:simple(assignmentDetails(s,r,'supervision'))}:{committeeMembers:[],supervisorMembers:[]};const next={};for(const [key,namesKey,group]of [['committeeMembers','committee','inspection'],['supervisorMembers','supervisors','supervision']]){let members=row[key]||row[namesKey]?.map((name,i)=>({name,position:'',ordinal:i+1,duty:personnelDuty(group,i+1)}))||[];next[key]=members.length?simple(members):before[key];}return {index,record:{...row,...next,committee:next.committeeMembers.map(x=>x.name),supervisors:next.supervisorMembers.map(x=>x.name)},registryId:r?.id,errors,changes:canonicalData(before)===canonicalData(next)?[]:importChanges(before,next)};});}
export function applyPersonnelImport(s,preview,selected){const next=cloneForMutation(s),at=new Date().toISOString();let updated=0,unchanged=0,created=0,updatedPeople=0;for(const x of preview){if(selected&&!selected.includes(String(x.index)))continue;if(x.errors.length)throw Error(x.errors.join(' · '));updatedPeople+=seedPersonnelMasterPositions(next,[x.record]);const r=next.contractRegistry.find(r=>r.id===x.registryId);if(!x.changes.length){unchanged++;continue;}for(const [key,group]of [['committeeMembers','inspection'],['supervisorMembers','supervision']])if(x.record[key]?.length)created+=setContractPersonnel(next,r,group,x.record[key]);const old=s.contractRegistry.find(v=>v.id===r.id);r.dataChange={kind:'updated',at,source:'นำเข้า ก-4 ชื่อ ตำแหน่ง และบทบาท',changes:importChanges(old,r).filter(c=>!c.path.startsWith('dataChange'))};delete r.reviewedAt;const p=next.projects.find(p=>p.id===r.projectId);if(p)Object.assign(p,{supervisorId:principalSupervisor(next,r)?.personId||r.supervisorId,supervisor:(principalSupervisor(next,r)?shortSupervisor(principalSupervisor(next,r).name):''),supervisorIds:clone(r.supervisorIds||[]),committeeIds:clone(r.committeeIds||[])});updated++;}return {state:next,updated,unchanged,created,updatedPeople};}
