export const canonicalSectionName=v=>String(v||'').normalize('NFKC').replace(/\s+ตอน(?:ที่)?\s*[0-9๐-๙]+(?:\s*[-–]\s*[0-9๐-๙]+)?\s*$/u,'').replace(/\s*[-–]\s*/g,' - ').replace(/\s+/g,' ').trim();
export const contractorNameKey=v=>String(v||'').normalize('NFKC').toLowerCase().replace(/[\s.\-–()]/g,'');
