export function contractorCandidates(s,name){const raw=contractorNameKey(name);if(!raw)return {matches:[],suggestions:[]};let matches=s.contractors.filter(c=>[c.name,...(c.aliases||[])].some(n=>contractorNameKey(n)===raw));const verified=matches.filter(c=>!c.needsNameReview);if(verified.length)matches=verified;if(matches.length)return {matches,suggestions:[]};const similarity=(a,b)=>{if(a===b)return 1;let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const row=[i];for(let j=1;j<=b.length;j++)row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=row;}return 1-prev[b.length]/Math.max(a.length,b.length,1);};const core=contractorCore(name),suggestions=s.contractors.map(c=>({id:c.id,name:c.name,score:Math.max(...[c.name,...(c.aliases||[])].map(n=>similarity(core,contractorCore(n))))})).filter(c=>c.score>=.65).sort((a,b)=>b.score-a.score).slice(0,5);return {matches,suggestions};}
export function rememberContractorAlias(s,id,name){const c=s.contractors.find(x=>x.id===id);if(!c)throw Error('ไม่พบผู้รับจ้างที่เลือก');const key=contractorNameKey(name);if(!key||key===contractorNameKey(c.name))return;const owners=contractorCandidates(s,name).matches;if(owners.some(x=>x.id!==id&&!x.needsNameReview))throw Error('ชื่อจากไฟล์นี้ผูกกับผู้รับจ้างรายอื่นแล้ว กรุณาตรวจสอบก่อน');if((c.aliases||[]).some(x=>contractorNameKey(x)===key))return;c.aliases=[...new Set([...(c.aliases||[]),String(name).trim()])];}
