 for(const [i,tr]of [...doc.querySelectorAll('table')].filter(t=>!t.parentElement.closest('table')).flatMap(t=>[...t.rows]).entries()){grid[i]||=[];let c=0;for(const cell of tr.cells){while(grid[i][c]!==undefined)c++;const value=cell.innerHTML.replace(/<br\s*\/?\s*>/gi,'\n'),node=new DOMParser().parseFromString(value,'text/html'),content=node.body.textContent.trim();const rs=Math.min(100,cell.rowSpan||1),cs=Math.min(150,cell.colSpan||1);for(let r=0;r<rs;r++){grid[i+r]||=[];for(let k=0;k<cs;k++)grid[i+r][c+k]=r===0&&k===0?content:'';}c+=cs;}if(c>150||i>10000)throw Error('ตารางเกินขนาดที่รองรับ');}
