export function effectiveReportNames(s,r,p){const candidates=(s.reports||[]).filter(x=>x.end&&r.end&&x.end<=r.end).sort((a,b)=>b.end.localeCompare(a.end));const resolve=(key,field)=>{const direct=s.settings?.[key]?.[r.id]?.[p.id];if(direct!==undefined)return direct;const values=candidates.filter(x=>s.settings?.[key]?.[x.id]?.[p.id]!==undefined).map(x=>({from:x.end,value:s.settings[key][x.id][p.id]}));for(const item of s.settings?.reportNameHistory?.[p.id]||[])if(item.effectiveFrom<=r.end&&item[field]!==undefined)values.unshift({from:item.effectiveFrom,value:item[field]});return values.sort((a,b)=>b.from.localeCompare(a.from))[0]?.value;};return {title:resolve('reportDisplayNames','title'),supervisor:resolve('reportSupervisorNames','supervisor'),contractor:resolve('reportContractorNames','contractor')};}
export function setReportDisplayName(s,r,pid,value,supervisor=false){const key=supervisor==='contractor'?'reportContractorNames':supervisor?'reportSupervisorNames':'reportDisplayNames',field=supervisor==='contractor'?'contractor':supervisor?'supervisor':'title';s.settings[key]||={};s.settings[key][r.id]||={};s.settings[key][r.id][pid]=value;s.settings.reportNameHistory||={};const list=s.settings.reportNameHistory[pid]||=[];let item=list.find(x=>x.effectiveFrom===r.end);if(!item){item={effectiveFrom:r.end};list.push(item);}item[field]=value;}

function canonicalPaymentMonth(v){try{return parsePaymentMonth(v);}catch{return v;}}
