export function readPlannetSubset(rows,sheet='',date1904=false){const keys=rows[0].map(label=>plannetColumns.find(([,name])=>name===cleanSource(label).replace(/\s+25\d{2}$/,''))?.[0]);return rows.slice(1).filter(row=>row.some(x=>cleanSource(x))).map((row,i)=>{const out={sourceSheet:sheet,sourceRow:i+2,sourceProfile:'pn-export'};for(let c=0;c<keys.length;c++){const key=keys[c];if(!key)continue;let value=row[c]??'';if(key==='paymentMonth')value=parsePaymentMonth(typeof value==='number'&&date1904?value+1462:value);else if(registryDateKeys.has(key)&&value!=='')value=parseG3Date(typeof value==='number'&&date1904?value+1462:value);else if(plannetNumeric.has(key)&&cleanSource(value)!==''){value=Number(String(value).replace(/,/g,''));if(!Number.isFinite(value))throw Error('แถว '+(i+2)+' '+key+' ต้องเป็นตัวเลข');}else value=cleanSource(value);out[key]=value;}const routeKeys=['routeNumber','controlSection','sectionName','kmStart','kmEnd','routeNote','direction'],pieces=routeKeys.map(k=>String(out[k]||'').split('\n'));out.segments=[];for(let i=0;i<Math.max(...pieces.map(a=>a.length));i++){const seg=Object.fromEntries(routeKeys.map((k,j)=>[k,pieces[j][i]||'']));if(Object.values(seg).some(Boolean))out.segments.push(seg);}for(const k of routeKeys)delete out[k];if(out.paymentMonth){const m=out.paymentMonth.match(/^(\d{1,2})\/(\d{4})$/);out.paymentMonth=m?String(+m[2]>2400?+m[2]-543:+m[2])+'-'+m[1].padStart(2,'0'):out.paymentMonth;}return out;});}
