  if((r.funding||'DOH')===group&&r.year===year){
   if(!keys.has(contractKey(r.contract))){if(!r.deletedAt){deleteRegistryRecord(result.state,r.id);removed++;}}
   else if(r.projectId){const p=result.state.projects.find(p=>p.id===r.projectId);if(p)delete p.deletedAt;}
  }
