 for(const r of s.contractRegistry){r.funding||='DOH';r.extensions||=[];const lp=projById.get(r.projectId);if(lp&&!r.deletedAt)delete lp.deletedAt;r.originalEnd||=lp?.originalEnd||r.end;r.budgetAccountId=add('budgetAccounts',r.budgetAccount,'BUD');r.workCodeId=add('workCodes',r.workCode,'WKC');r.workNameId=add('workNames',r.title,'JOB');const job=getById('workNames').get(r.workNameId);if(job){job.typeId||=r.workTypeId||'';job.codeIds||=[];if(r.workCodeId&&!job.codeIds.includes(r.workCodeId))job.codeIds.push(r.workCodeId);}if(r.personnelManaged)r.supervisorId=r.supervisorIds?.[0]||'';else r.supervisorId||=lp?.supervisorId||(r.supervisor?add('supervisors',r.supervisor,'SUP'):'');if(r.supervisorId&&!getById('supervisors').has(r.supervisorId))r.supervisorId=r.supervisor?add('supervisors',r.supervisor,'SUP'):'';if(r.contractorId&&!getById('contractors').has(r.contractorId))r.contractorId=r.contractorRaw&&!r.contractorNeedsReview?add('contractors',r.contractorRaw,'CTR'):'';delete r.archived;}
