export function registryRecords(s,year,funding){ensureRegistry(s);return s.contractRegistry.filter(r=>!r.deletedAt&&r.year===year&&(r.funding||'DOH')===funding);}
export function projectFromRegistry(s,r){const old=s.projects.find(p=>p.id===r.projectId);return {...clone(old||{}),id:r.projectId||'PN-'+r.id,registryId:r.id,contract:r.contract,year:r.year,funding:r.funding||'DOH',title:r.title,category:old?.category||'UNCATEGORIZED',start:r.start,end:r.end,originalEnd:r.originalEnd||old?.originalEnd||r.end,duration:+r.duration,extensions:clone(r.extensions||old?.extensions||[]),contractorId:r.contractorId||'',contractor:s.contractors?.find(x=>x.id===r.contractorId)?.name||r.contractorRaw||'',supervisorId:principalSupervisor(s,r)?.personId||r.supervisorId||'',supervisor:r.personnelImported?(principalSupervisor(s,r)?shortSupervisor(principalSupervisor(s,r).name):''):s.supervisors?.find(x=>x.id===r.supervisorId)?.name||r.supervisor||'',workNameId:r.workNameId||'',workTypeId:r.workTypeId||'',workCodeId:r.workCodeId||'',budgetAccountId:r.budgetAccountId||'',extras:clone(r.extras||old?.extras||{}),archived:!!r.deletedAt};}
export function linkRegistryForReport(s,year,funding){const rows=registryRecords(s,year,funding);for(const r of rows){const p=projectFromRegistry(s,r);r.projectId=p.id;const i=s.projects.findIndex(x=>x.id===p.id);if(i<0)s.projects.push(p);else s.projects[i]=p;}if(rows.length&&!s.categories?.some(x=>x.id==='UNCATEGORIZED')){s.categories||=[];s.categories.push({id:'UNCATEGORIZED',name:'ยังไม่ระบุหมวดเดิม'});}return rows;}
export function contractDatePatch(entry,values){return Object.fromEntries(['deliveryDate','acceptanceDate','paymentDate'].filter(k=>String(values[k]||'')!==String(entry[k]||'')).map(k=>[k,String(values[k]||'')]));}
