export function deleteRegistryRecord(s,id){ensureRegistry(s);const r=s.contractRegistry.find(x=>x.id===id);if(!r)throw Error('ไม่พบสัญญา');const used=s.reports.some(x=>x.entries?.[r.projectId]);if(used){r.deletedAt=new Date().toISOString();delete r.archived;const p=s.projects.find(p=>p.id===r.projectId);if(p){p.deletedAt=r.deletedAt;delete p.archived;}}else{s.contractRegistry=s.contractRegistry.filter(x=>x.id!==id);s.projects=s.projects.filter(p=>p.id!==r.projectId);}return used?'retained-history':'deleted';}
export function compareData(a,b,key,direction=1){const av=key.split('.').reduce((v,k)=>v?.[k],a),bv=key.split('.').reduce((v,k)=>v?.[k],b);if(av==null||av==='')return bv==null||bv===''?0:1;if(bv==null||bv==='')return -1;const numeric=['duration','contractValue','actualCost','quantity','e.plan','e.weekly','e.actual'].includes(key);return direction*(numeric?Number(av)-Number(bv):String(av).localeCompare(String(bv),'th',{numeric:true,sensitivity:'base'}));}

