let registrySyncRunning=false,registrySyncFailure='';
async function synchronizeReport(id=selected){
 const r=state.reports.find(r=>r.id===id);if(registrySyncRunning||!r||r.id==='EMPTY'||r._unloaded||!reportMatchesScope(state,r,year,funding))return;
 if(state.loadedScope&&(state.loadedScope.year!==year||state.loadedScope.funding!==funding))return;
 const a=reportLinkAudit(state,r,year,funding);if(!a.missing.length){registrySyncFailure='';return;}
 if(a.duplicates.length||a.unresolved.length||a.outside.length){registrySyncFailure='เชื่อมโยงไม่สำเร็จ: พบรายการซ้ำหรืออ้างอิงไม่ครบ กรุณาเปิดไอคอนลิงก์เพื่อตรวจสอบ';return;}
 registrySyncRunning=true;
 try{await mutate('เชื่อมโยงสัญญาเข้ารายงานอัตโนมัติ',s=>{fillMissingReportContracts(s,id,{automatic:true});},{format:'CSV',fileName:'เชื่อมโยงทะเบียนสัญญาอัตโนมัติ'});registrySyncFailure='';}
 catch(e){registrySyncFailure='เชื่อมโยงสัญญาไม่สำเร็จ: '+e.message;}
 finally{registrySyncRunning=false;}
}

