const previousCache=new WeakMap();
function previousEntry(r,id){let cache=previousCache.get(state);if(!cache){cache=new Map();previousCache.set(state,cache);}if(!cache.has(r.id)){const entries={};for(const x of state.reports.filter(x=>x.id!==r.id&&x.end&&r.start&&x.end<r.start&&(x.funding||'DOH')===(r.funding||'DOH')&&(!x.year||x.year===r.year)).sort((a,b)=>b.end.localeCompare(a.end)))for(const [pid,e]of Object.entries(x.entries))entries[pid]??=e;cache.set(r.id,{...(state.settings.reportBaselines?.[r.id]||{}),...((r.id===state.loadedScope?.reportId?state.loadedScope.previousEntries:state.loadedScope?.latestEntries)||{}),...entries});}const e=cache.get(r.id)[id];return e?{...e,paymentDate:e.paymentDate||parsePaymentDate(e.note)}:undefined;}
let activeRowsCache;const activeRows=()=>activeRowsCache??=rowsFor({...state,activeFunding:funding},report(),year);
