 const index=head.cellIndex,values=data?data.map(row=>row[column]):[...table.tBodies[0]?.rows||[]].map(row=>row.cells[index]?.textContent);
 ctx.font=getComputedStyle(table.tBodies[0]?.rows[0]?.cells[index]||head).font;
