 await synchronizeReport();const r=report();if(r.id==='EMPTY')return toast('กรุณาสร้างรายงานก่อน',true);const a=reportLinkAudit(state,r,year,funding),visible=reportRowsMatching(activeRows()).length,hidden=a.visibleCount-visible;
