async function submitWeeklyEdit(reportId,id,k,value){const key=reportId+'|'+id+'|'+k,token=uid();editDrafts.set(key,{reportId,id,k,value,token});persistEdits();try{if(state.reports.find(r=>r.id===reportId)?.locked){const patch={[k]:value},r=state.reports.find(r=>r.id===reportId),prev=previousEntry(r,id)||{actual:0};if(k==='weekly')patch.actual=+(Number(prev.actual)+value).toFixed(2);if(k==='actual')patch.weekly=+(value-Number(prev.actual)).toFixed(2);await saveAmendment(reportId,{[id]:patch},{inlineId:id});}else await mutate('อัปเดตผลงาน '+id,s=>{const r=s.reports.find(x=>x.id===reportId);if(r.locked)throw Error('รายงานถูกปิดแล้ว');const e=r.entries[id];e[k]=value;if(k==='payment'){if(value==='เบิกจ่ายแล้ว'){e.paymentDate||=report().reference||today();e.note=paymentNote(e);}else{if(e.note?.startsWith('เบิกจ่ายแล้ว วันที่ '))e.note='';e.paymentDate='';}}if(k==='paymentDate'){if(!value)throw Error('กรุณาเลือกวันที่เบิกจ่าย');e.note=paymentNote(e);}const prev=previousEntry(r,id);if(k==='weekly')e.actual=+(Number(prev?.actual||0)+value).toFixed(2);if(k==='actual')e.weekly=+(value-Number(prev?.actual||0)).toFixed(2);validateDates(e);if(k!=='confirmed')e.confirmed=false;if(['weekly','actual','confirmed','payment','paymentDate'].includes(k))validateEntry(e,prev||{actual:0});else validateEntry(e);if(['note','payment','paymentDate','deliveryDate','acceptanceDate'].includes(k))syncContractDates(s,id,e,(k==='payment'?['paymentDate','payment','note']:[k]).filter(key=>!['note','payment'].includes(key)||!s.reports.some(later=>later.end>r.end&&later.entries?.[id])));},undefined,undefined,{reportId,id});if(editDrafts.get(key)?.token===token)editDrafts.delete(key);persistEdits();if(view==='weekly'&&selected===reportId)updateWeeklyRowDOM(id);else restoreEdits();}catch(e){if(editDrafts.get(key)?.token===token)editDrafts.get(key).error=e.message;persistEdits();toast(e.message,true);restoreEdits();}}
function bindSettings(){$('#settings-layout')?.addEventListener('click',async()=>{try{await ensureScope();await preview(true);}catch(e){toast(e.message,true);}});$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{let logo='';const file=$('#logo-file').files?.[0];if(file){if(file.type!=='image/png'||file.size>500000)throw Error('เลือก PNG ขนาดไม่เกิน 500 KB');logo=await readPNG(file);}const saveSettings=()=>mutate('แก้ไขรูปแบบรายงาน',s=>{s.settings.organization=f.get('organization');s.settings.reportTitles={DOH:f.get('titleDOH').trim(),PROVINCE:f.get('titleProvince').trim()};s.settings.title=s.settings.reportTitles.DOH;s.settings.systemName=String(f.get('systemName')).trim();if(f.get('removeLogo'))s.settings.logo='';if(logo)s.settings.logo=logo;});if(f.get('removeLogo'))confirmAction('ยืนยันลบโลโก้','ลบโลโก้ปัจจุบันออกจากระบบและบันทึกการตั้งค่านี้',saveSettings);else await saveSettings();}catch(err){toast(err.message,true);}});$('#cloud-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const f=new FormData(e.target);try{cloud.setConfig(f.get('url'),f.get('key'));const data=await loadWorkspace();if(data){validateLoadedWorkspace(data);state=data;selected=state.reports[0].id;year=state.years[0];await cacheWorkspace(state);cloudMode=true;render();toast('โหลดข้อมูลจาก Supabase แล้ว ไม่ต้องเข้าสู่ระบบ');}else{state.revision=0;cloudMode=true;render();toast('เชื่อมต่อแล้ว ฐานข้อมูลยังว่าง กดนำเข้าข้อมูล JSON เพื่อเริ่มใช้งาน');}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});}
