async function loadWorkspace(scope){const data=await cloud.loadCloud({...scope||{funding,year},screen:true});if(data?.referenceDeferred){let cached;try{cached=JSON.parse(localStorage.getItem('pn-weekly-branding')||'null');}catch{}const branding=await cloud.loadBrandingCloud(cached?.hash);const asset=branding?.notModified?cached:branding;if(asset&&typeof asset.logo==='string'){data.settings.logo=asset.logo;try{localStorage.setItem('pn-weekly-branding',JSON.stringify(asset));}catch{}}}if(data)data.importHistoryDeferred=true;if(data&&!data.contractors){normalizeState(data);const result=await cloud.saveCloud(data,data.revision||0);data.revision=result.revision;}return data;}
function weekLabel(r){if(/^สัปดาห์ที่/.test(r.title))return r.title;const n=r.title.match(/(?:รอบที่|สัปดาห์ที่)\s*(\d+)/);return 'สัปดาห์ที่ '+(n?.[1]||state.reports.filter(x=>(!x.year||x.year===year)&&(!x.funding||x.funding===funding)).slice().sort((a,b)=>(a.end||'').localeCompare(b.end||'')).findIndex(x=>x.id===r.id)+1);}
