 n.extras={...r.extras};for(const c of(s.settings.customFields||[]))n.extras[c.id]=String(f.get('extra_'+c.id)||'');for(const [key,input,link]of [['budgetAccounts','budgetAccount','budgetAccountId'],['workCodes','workCode','workCodeId'],['workNames','title','workNameId'],['workTypes','workTypeName','workTypeId'],['contractors','contractorName','contractorId'],['supervisors','supervisorName','supervisorId']]){const name=String(f.get(input)||'').trim(),item=s[key].find(x=>x.name===name&&(!x.archived||x.id===r[link]));if(name&&!item){const created={id:key.toUpperCase()+'-'+uid(),name};s[key].push(created);n[link]=created.id;}else n[link]=item?.id||'';}
 if(!n.contractorId&&!n.contractorRaw)throw Error('เลือกผู้รับจ้าง หรือเพิ่มชื่อผู้รับจ้างก่อน');if(n.contractorId){const c=s.contractors.find(x=>x.id===n.contractorId);if(n.contractorRaw){const owners=contractorCandidates(s,n.contractorRaw).matches;if(!owners.some(x=>x.id!==c.id&&!x.needsNameReview))rememberContractorAlias(s,c.id,n.contractorRaw);}else n.contractorRaw=c.name;c.needsNameReview=false;}n.contractorNeedsReview=!n.contractorId;
 n.note=String(f.get('note')||'');n.payment=String(f.get('payment')||'รอส่งมอบงาน');if(n.payment==='เบิกจ่ายแล้ว'&&(!n.finalPaymentDate||registryCurrent(s,r).currentActual<100))throw Error('เบิกจ่ายแล้วต้องมีผลงานสะสม 100% และวันที่เบิกจ่ายครบ');for(const key of ['budgetAct','allocatedBudget','poAmount','carryBudget','paidFiscal','paidCarry']){const raw=f.get(key);n[key]=raw===''?'':Number(raw);if(raw!==''&&(!Number.isFinite(n[key])||n[key]<0))throw Error('วงเงินต้องเป็นตัวเลขไม่ติดลบ');}n.segments=readSegmentForm(f,r);const members=personnelFromForm(f);for(const group of ['inspection','supervision'])setContractPersonnel(s,n,group,members[group]);if(r.personnelImported||n.supervisorIds?.length){n.supervisorId=n.supervisorIds?.[0]||'';n.supervisor=s.supervisors.find(x=>x.id===n.supervisorId)?.name||'';}const check=previewRegistryImport(s,[n],n.year,n.funding)[0];if(check.errors.length)throw Error(check.errors.join(', '));validateDates({deliveryDate:n.deliveryDate,acceptanceDate:n.acceptanceDate,paymentDate:n.finalPaymentDate,payment:n.finalPaymentDate?'เบิกจ่ายแล้ว':'รอเบิกจ่าย'});
 if(s.contractRegistry.some(x=>x.id!==n.id&&x.year===n.year&&(x.funding||'DOH')===n.funding&&contractKey(x.contract)===contractKey(n.contract)))throw Error('เลขสัญญาซ้ำในกลุ่มงบและปีนี้');const p=s.projects.find(x=>x.id===r.projectId);if(p&&s.reports.some(x=>x.entries[p.id])&&(p.year!==n.year||(p.funding||'DOH')!==n.funding))throw Error('สัญญามีรายงานแล้ว ไม่สามารถย้ายกลุ่มงบหรือปีได้');n.originalEnd=addDays(n.end,-(n.extensions||[]).filter(x=>x.approved).reduce((total,x)=>total+x.days,0));n.updatedAt=new Date().toISOString();const i=s.contractRegistry.findIndex(x=>x.id===n.id);if(i<0)s.contractRegistry.push(n);else s.contractRegistry[i]=n;
