function syncDatesToEntry(e,r,before={}){for(const [target,key]of [['note','note'],['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate'],['payment','payment']])if(r[key]!==before[key])e[target]=r[key]||'';if(e.payment==='เบิกจ่ายแล้ว'){if(!e.paymentDate)throw Error('รายงานฉบับร่างที่เบิกจ่ายแล้วต้องมีวันที่เบิกจ่าย');e.note=paymentNote(e);}}
function bindRegistryMasters(){const form=$('#contract-form');const inputFor=key=>form.querySelector(`[data-master-key="${key}"]`);const refresh=()=>{const code=state.workCodes.find(x=>x.name===inputFor('workCodes').value.trim()),type=state.workTypes.find(x=>x.name===inputFor('workTypes').value.trim());$$('#contract-form [data-master-key]').forEach(input=>{const key=input.dataset.masterKey;let rows=state[key].filter(x=>!x.deletedAt);if(key==='workNames')rows=rows.filter(x=>(!type||x.typeId===type.id)&&(!code||x.codeIds?.includes(code.id)));const text=input.value.trim();$('#registry-list-'+key).innerHTML=rows.filter(x=>!text||x.name.toLowerCase().includes(text.toLowerCase())).map(x=>`<option value="${esc(x.name)}">`).join('');form.querySelector(`[data-registry-add-master="${key}"]`).hidden=!text||state[key].some(x=>x.name===text&&!x.archived);});};
 $$('#contract-form [data-master-key]').forEach(input=>{input.oninput=refresh;input.onchange=()=>{if(input.dataset.masterKey==='workCodes'){const code=state.workCodes.find(x=>x.name===input.value.trim()),jobs=state.workNames.filter(x=>!x.archived&&x.codeIds?.includes(code?.id));if(jobs.length===1){inputFor('workNames').value=jobs[0].name;inputFor('workTypes').value=state.workTypes.find(x=>x.id===jobs[0].typeId)?.name||inputFor('workTypes').value;}}refresh();};});
 $$('#contract-form [data-registry-add-master]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const key=b.dataset.registryAddMaster,input=inputFor(key),name=input.value.trim();await mutate('เพิ่มรายการพื้นฐาน '+name,s=>{if(!name||s[key].some(x=>x.name===name&&!x.archived))throw Error('ชื่อว่างหรือมีอยู่แล้ว');const archivedItem=s[key].find(x=>x.name===name&&x.archived);if(archivedItem){archivedItem.archived=false;return;}const item={id:key.toUpperCase()+'-'+uid(),name,archived:false};if(key==='workNames'){item.typeId=s.workTypes.find(x=>x.name===inputFor('workTypes').value.trim())?.id||'';const code=s.workCodes.find(x=>x.name===inputFor('workCodes').value.trim());if(!code)throw Error('กรุณาเลือกรหัสงานก่อนเพิ่มชื่องาน');if(s.workNames.some(w=>w.codeIds?.includes(code.id)))throw Error('รหัสงานนี้จับคู่กับชื่องานอื่นแล้ว');item.codeIds=[code.id];}s[key].push(item);});refresh();input.focus();}catch(e){showFormError(form,e.message);}finally{b.disabled=false;}});refresh();}
function registryExtensionDialog(id){const r=state.contractRegistry.find(x=>x.id===id);modal('บันทึกขยายอายุสัญญา · '+r.contract,`<form><div class="form-grid">${field('เลขหนังสืออนุมัติ','reference','','text','required')}${field('วันที่อนุมัติ','approvedAt',today(),'date','required')}${field('จำนวนวันเพิ่ม','days',7,'number','min="1" step="1" required')}${field('วันสิ้นสุดใหม่','end',addDays(r.end,7),'date','required')}</div>${buttons('บันทึกการอนุมัติ')}</form>`,f=>mutate('ขยายสัญญา '+r.contract,s=>{const n=s.contractRegistry.find(x=>x.id===id),d=+f.get('days');if(!Number.isInteger(d)||d<1||addDays(n.end,d)!==f.get('end'))throw Error('วันสิ้นสุดใหม่ต้องเท่ากับวันเดิมบวกวันขยาย');if(n.extensions.some(x=>x.reference===String(f.get('reference')).trim()))throw Error('เลขหนังสือซ้ำ');n.extensions.push({id:uid(),days:d,end:f.get('end'),reference:String(f.get('reference')).trim(),approvedAt:f.get('approvedAt'),approved:true});n.end=f.get('end');n.updatedAt=new Date().toISOString();const p=s.projects.find(x=>x.id===n.projectId);if(p){Object.assign(p,projectFromRegistry(s,n));if(!n.deletedAt)delete p.deletedAt;};}));$('#modal [name=days]').oninput=e=>$('#modal [name=end]').value=addDays(r.end,+e.target.value||0);}
async function ensureFirstWeekly(){if(view!=='weekly')return;const found=state.reports.find(r=>reportMatchesScope(state,r,year,funding));selected=found?.id;}
function weeklySummary(rows){const labels=[['all','ทั้งหมด'],['ongoing','กำลังดำเนินการ'],['pay','รอเบิกจ่าย'],['paid','เบิกจ่ายแล้ว'],['expired','หมดอายุ · ยังดำเนินการ']];return `<section class="register-summary weekly-summary" aria-label="สรุปสถานะสัญญา"><div class="summary-items">${labels.map(([key,label])=>`<button data-filter="${key}" class="summary-count status-${key} ${filter===key?'selected':''}"><span>${label}</span><strong>${key==='all'?rows.length:rows.filter(x=>key==='expired'?weeklyExpired(x.p,x.e,report().reference||report().end):statusKey(x.e)===key).length}</strong></button>`).join('')}</div></section>`;}
function contractDatesDialog(pid){const r=report(),saved=r.entries[pid],reg=state.contractRegistry.find(x=>x.projectId===pid),e={...saved,...Object.fromEntries([['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate']].map(([k,rk])=>[k,reg?.[rk]||saved[k]||'']))},p=projectAt(state,r,pid);modal('วันที่ส่งมอบ ตรวจรับ และเบิกจ่าย · '+p.contract,`<form><div class="form-grid">${field('วันส่งมอบงาน','deliveryDate',e.deliveryDate||'','date')}${field('วันตรวจรับงาน','acceptanceDate',e.acceptanceDate||'','date')}${field('วันที่เบิกจ่าย','paymentDate',e.paymentDate||'','date',e.payment==='เบิกจ่ายแล้ว'?'required':'')}</div>${buttons('บันทึกวันที่')}</form>`,async f=>{const patch=contractDatePatch(e,Object.fromEntries(['deliveryDate','acceptanceDate','paymentDate'].map(k=>[k,String(f.get(k)||'')])));if(!Object.keys(patch).length)throw Error('ยังไม่มีข้อมูลเปลี่ยนแปลง');validateDates({...e,...patch});if(r.locked)await saveAmendment(r.id,{[pid]:patch});else await mutate('บันทึกวันที่สัญญา',s=>{const entry=s.reports.find(x=>x.id===r.id).entries[pid];Object.assign(entry,patch);if(entry.payment==='เบิกจ่ายแล้ว')entry.note=paymentNote(entry);entry.confirmed=false;syncContractDates(s,pid,entry,[...Object.keys(patch),...(entry.payment==='เบิกจ่ายแล้ว'?['note']:[])]);});});}
function bindRegistry(){bindSortHeaders();$$('[data-budget-filter]').forEach(b=>b.onclick=()=>{budgetFilter=b.dataset.budgetFilter;page=1;render();});$$('[data-registry-view]').forEach(b=>b.onclick=e=>{e.stopPropagation();registryDetailDialog(b.dataset.registryView);});$$('[data-registry-edit]').forEach(b=>b.onclick=e=>{e.stopPropagation();registryEditDialog(b.dataset.registryEdit);});$$('[data-registry-delete]').forEach(b=>b.onclick=e=>{e.stopPropagation();registryDelete(b.dataset.registryDelete);});$$('[data-registry-row]').forEach(row=>{row.onclick=e=>{if(!e.target.closest('button'))registryDetailDialog(row.dataset.registryRow);};row.onkeydown=e=>{if(e.target===row&&['Enter',' '].includes(e.key)){e.preventDefault();registryDetailDialog(row.dataset.registryRow);}};});$('#registry-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=1;render();$('#registry-search').focus();$('#registry-search').setSelectionRange(pos,pos);});$$('[data-registry-page]').forEach(b=>b.onclick=()=>{page=+b.dataset.registryPage;render();});$$('[data-contract-dates]').forEach(b=>b.onclick=()=>contractDatesDialog(b.dataset.contractDates));}
function bindSortHeaders(){$$('[data-sort-scope]').forEach(b=>b.onclick=()=>{const sort=b.dataset.sortScope==='registry'?registrySort:weeklySort;sort.dir=sort.key===b.dataset.sortKey?-sort.dir:1;sort.key=b.dataset.sortKey;page=1;render();});}

let importScopeRequest=0;async function ensureImportScope(form){const token=++importScopeRequest,requested={funding:form.elements.funding.value,year:+form.elements.year.value};if(cloudMode&&state.loadedScope&&(state.loadedScope.funding!==requested.funding||state.loadedScope.year!==requested.year||state.referenceDeferred)){const loaded=await cloud.loadCloud(requested);if(token!==importScopeRequest||!form.isConnected||form.elements.funding.value!==requested.funding||+form.elements.year.value!==requested.year)return false;state=loaded;normalizeState(state);funding=requested.funding;year=requested.year;selected=state.loadedScope.reportId;await cacheWorkspace(state);}return token===importScopeRequest&&form.isConnected;}

function contractorMatchField(item){const name=item.record.contractorRaw;if(!name)return '';const {matches,suggestions}=contractorCandidates(state,name),exact=matches.length===1?matches[0]:null,ids=[...new Set([...suggestions.map(x=>x.id),...state.contractors.map(x=>x.id)])];return `<label class="contractor-match">ผู้รับจ้างจากไฟล์: ${esc(name)}<select data-contractor-choice="${item.index}" aria-label="จับคู่ผู้รับจ้างแถว ${item.index+1}"><option value="">${matches.length>1?'ชื่อซ้ำหลายราย — กรุณาเลือก':suggestions.length?'ยังไม่ยืนยัน — เพิ่มเป็นชื่อใหม่รอตรวจ':'ไม่พบชื่อ — เพิ่มใหม่รอตรวจ'}</option>${ids.map(id=>{const c=state.contractors.find(x=>x.id===id);return `<option value="${esc(id)}" ${exact?.id===id?'selected':''}>${esc(c.name)}${suggestions.some(x=>x.id===id)&&!exact?' (ชื่อใกล้เคียง)':''}</option>`;}).join('')}</select></label>`;}
function registryImportDialog(excel=false){let records=[],preview=[],sourceName='';modal(excel==='emergency'?'นำเข้าแบบ ก-3 งบฉุกเฉิน':excel?'นำเข้าแบบ ก-3':'นำเข้ารูปแบบระบบ',`<form id="registry-import"><div class="form-grid">${selectField('กลุ่มงบ','funding',state.fundingSources.map(x=>({value:x.id,label:x.name})),funding)}${selectField('ปีงบประมาณ','year',[...state.years].sort((a,b)=>b-a),year)}<label class="field wide">${excel?'ไฟล์ Excel แบบ ก-3 (.xlsx / .xls)':'ไฟล์รูปแบบระบบ (.xlsx / .csv)'}<input id="registry-file" type="file" accept="${excel?'.xlsx,.xls':'.xlsx,.csv'}" required></label></div><p class="hint">จำเป็น: เลขสัญญา ชื่องาน เริ่มต้นสัญญา วันสิ้นสุดปัจจุบัน ระยะเวลาเดิม (วัน) · ปีและกลุ่มงบเว้นว่างเพื่อใช้ค่าที่เลือกได้ · จับคู่ด้วย ID ก่อน แล้วจึงเลขสัญญาเมื่อไม่มี ID · รายการนอกไฟล์คงเดิม · ช่องว่างคงค่าเดิม · รายการใหม่เว้น ID และ workspace_id ว่าง ระบบสร้าง ID และใช้พื้นที่ปัจจุบันอัตโนมัติ · แบบ ก-3 ใช้วงเงินสัญญาแยกจาก PO · รวมโครงการเป็นยอดเบิกจ่ายสะสม · จับคู่ ID Code ก่อนเลขสัญญา</p><button type="button" class="btn primary" id="load-registry-file">${'อ่านไฟล์และตรวจข้อมูล'}</button><div id="registry-import-preview"></div><p class="form-error" role="alert"></p></form>`);const form=$('#registry-import');form.elements.funding.value=funding;form.elements.year.value=String(year);const show=()=>{preview=previewRegistryImport(state,records,+form.elements.year.value,form.elements.funding.value).map(x=>({...x,changes:csvPreviewChanges(state,'registry',x)}));const duplicates=preview.filter(x=>x.duplicateId||x.fileDuplicate).length,errors=preview.filter(x=>x.errors.length).length;$('#registry-import-preview').innerHTML=`<div class="notice">อ่านได้ ${records.length} รายการ · ซ้ำ ${duplicates} · มีปัญหา ${errors} · เพิ่มประเภทงานจากไฟล์ ${new Set(preview.map(x=>x.record.pendingWorkTypeName).filter(Boolean)).size} รายการ</div><div class="table-scroll import-scroll"><table data-selection-key="import-registry" data-selection-ids="${esc(JSON.stringify(preview.map(x=>String(x.index))))}"><thead><tr><th>แถว / สัญญา</th><th>ชื่องาน</th><th>ตรวจสอบ</th><th>การนำเข้า</th></tr></thead><tbody>${preview.map(item=>`<tr data-select-id="${item.index}"><td>${item.record.sourceRow||item.record.csvRow||item.index+1}<br>${esc(item.record.contract)}${item.record.id?`<br><small class="sub">${esc(item.record.id)}</small>`:''}</td><td>${esc(item.record.title)}${contractorMatchField(item)}${!item.errors.length&&!item.fileDuplicate?csvChangeHTML(item.changes,state):''}</td><td>${esc(item.errors.join(' | ')||((item.duplicateId||item.fileDuplicate)?'เลขสัญญาซ้ำ':'')||(Array.isArray(item.record.warnings)?item.record.warnings.join(' | '):String(item.record.warnings||'')))}</td><td>${item.duplicateId||item.fileDuplicate||item.errors.length?`<select data-import-choice="${item.index}">${!item.errors.length?'<option value="overwrite">บันทึกทับค่าเดิม</option>':''}<option value="skip" ${item.fileDuplicate?'selected':''}>ข้าม</option></select>`:'เพิ่มใหม่'}</td></tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button type="button" class="btn" id="download-registry-csv">ดาวน์โหลด Excel</button><button type="button" class="btn primary" id="commit-registry-import">นำเข้าเพิ่ม / อัปเดตทะเบียน</button></div>`;selectionAdapters.set('import-registry',ids=>download(registryXLSX(records.filter((_,index)=>ids.includes(String(index)))),'ตัวอย่างทะเบียนที่เลือก.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'));mountSelections();if(excel){$('#download-registry-csv').remove();$('#registry-import-preview').querySelector('[data-selection-export]')?.remove();}else $('#download-registry-csv').onclick=()=>download(registryXLSX(records),'ทะเบียนสัญญา.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');$('#commit-registry-import').onclick=async()=>{const b=$('#commit-registry-import');await commitCSVForm(b,async()=>{const chosen=new Set(selectionFor('import-registry',preview.map(x=>x.index))),choices={};for(const item of preview)if(!chosen.has(String(item.index)))choices[item.index]='skip';$$('[data-import-choice]').forEach(x=>{if(chosen.has(x.dataset.importChoice))choices[+x.dataset.importChoice]=x.value;});$$('[data-contractor-choice]').forEach(el=>{const row=preview[+el.dataset.contractorChoice].record;if(el.value)row.contractorChoiceId=el.value;else delete row.contractorChoiceId;});let result;await mutate('นำเข้าทะเบียนสัญญา',s=>{const prior=cloneForMutation(s);result=applyRegistryImport(s,preview,choices);Object.assign(s,result.state);if(result.added+result.updated)captureImportResult(s,'contractRegistry',prior,sourceName);},{fileName:sourceName||'ทะเบียนสัญญา.csv',format:/\.xlsx$/i.test(sourceName)?'XLSX':'CSV'});year=+form.elements.year.value;funding=form.elements.funding.value;$('#modal').close();render();toast(`นำเข้าแล้ว: เพิ่ม ${result.added} ทับ ${result.updated} ข้าม ${result.skipped} ไม่เปลี่ยน ${result.unchanged}`);},e=>toast(e.message,true));};};$('#load-registry-file').onclick=async()=>{const b=$('#load-registry-file');b.disabled=true;try{const file=$('#registry-file').files[0];if(!file)throw Error('เลือกไฟล์ก่อน');if(/\.xlsx?$/i.test(file.name)){const result=await readG3Workbook(await file.arrayBuffer(),excel==='emergency'?'emergency':excel?'plannet':'registry');records=result.records;if(excel==='emergency')records=records.map(r=>({...r,budgetAccount:'งบฉุกเฉิน',budgetAccountSource:'งบฉุกเฉิน'}));if(result.fiscalYear){if(![...form.elements.year.options].some(o=>+o.value===result.fiscalYear))form.elements.year.add(new Option(String(result.fiscalYear),String(result.fiscalYear)));form.elements.year.value=String(result.fiscalYear);}}else{if(file.size>10000000)throw Error('CSV ต้องไม่เกิน 10 MB');records=parseRegistryCSV(await file.text());}sourceName=file.name;if(!await ensureImportScope(form))return;tableSelections.delete('import-registry');show();}catch(e){showFormError(form,e.message);}finally{b.disabled=false;}};$('#registry-file').onchange=()=>{records=[];preview=[];sourceName='';$('#registry-import-preview').innerHTML='';};form.elements.year.onchange=form.elements.funding.onchange=async()=>{try{if(await ensureImportScope(form)&&records.length)show();}catch(e){showFormError(form,e.message);}};}

$('[data-brand-home],.brand')?.addEventListener('click',e=>{e.preventDefault();view='dashboard';filter='all';page=1;query='';category='';budgetFilter='';$('.sidebar').classList.remove('open');render();});$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#notifications').onclick=alerts;$('#modal').addEventListener('cancel',e=>e.preventDefault());window.addEventListener('beforeunload',e=>{if(pendingWrites||editDrafts.size||storageWarning){e.preventDefault();e.returnValue='';}});$('#modal').addEventListener('close',()=>{thaiCalendar?.destroy();thaiCalendar=null;$('#modal').style.width='';});document.addEventListener('click',e=>{const history=e.target.closest('[data-history-detail]');if(history){void cloud.loadHistoryChangeCloud(history.dataset.historyDetail,+history.dataset.historyIndex).then(d=>modal('รายละเอียดการเปลี่ยนแปลง',`<pre class="history-full-value">${esc(JSON.stringify(d.change,null,2))}</pre>`)).catch(e=>toast(e.message,true));return;}const review=e.target.closest('[data-review-import]');if(review){reviewLastImport();return;}const ep=e.target.closest('[data-expired-page]');if(ep){expiredPage=+ep.dataset.expiredPage;render();return;}const roadLibrary=e.target.closest('[data-road-library]');if(roadLibrary){roadLibraryDialog();return;}const library=e.target.closest('[data-personnel-library]');if(library){personnelLibraryDialog();return;}const title=e.target.closest('[data-report-name]');if(title){e.preventDefault();e.stopPropagation();startInlineReportName(title.dataset.reportName,title.dataset.nameKind||'title');return;}const qm=e.target.closest('[data-quality-mode]');if(qm){qualityMode=qm.dataset.qualityMode;qualityPage=1;render();return;}const qr=e.target.closest('[data-quality-review]');if(qr){const id=qr.dataset.qualityReview;void withButtonLock(qr,()=>mutate('ตรวจประเด็นข้อมูล',s=>{s.settings.qualityReviews||={};if(qualityMode==='reviewed')delete s.settings.qualityReviews[id];else s.settings.qualityReviews[id]={at:new Date().toISOString()};}),err=>toast(err.message,true));return;}const b=e.target.closest('[data-review-record]');if(b){e.preventDefault();e.stopPropagation();changeReviewDialog(b.dataset.reviewRecord);}},true);document.addEventListener('click',e=>{if(!e.target.closest('.file-menu')||e.target.closest('.file-menu button'))$$('.file-menu[open]').forEach(m=>m.open=false);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const menu=$('.file-menu[open]');if(menu&&!$('#modal').open){menu.open=false;menu.querySelector('summary').focus();}$('.sidebar').classList.remove('open');}});await synchronizeReport();render();if(navigator.onLine&&outbox.length)void flushOutbox();if(connectionError)toast('ยังไม่เชื่อมต่อ Supabase: '+connectionError,true);

